CREATE TABLE IF NOT EXISTS public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, sale_id uuid NOT NULL REFERENCES public.sales(id) ON DELETE RESTRICT, contract_id uuid REFERENCES public.hire_purchase_contracts(id) ON DELETE RESTRICT, driver_id uuid NOT NULL REFERENCES public.drivers(id) ON DELETE RESTRICT, amount numeric NOT NULL CHECK (amount > 0), payment_method text NOT NULL CHECK (payment_method IN ('CASH','MOBILE_MONEY','BANK_TRANSFER','CARD','ONLINE','OTHER')), reference text, receipt_number text NOT NULL, paid_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'POSTED', reconciliation_status text NOT NULL DEFAULT 'UNMATCHED', received_by uuid, notes text, created_at timestamptz NOT NULL DEFAULT now());